    "descripcion": "El crossplay masculino suele generar dudas e inseguridades en muchas personas que desean explorarlo por primera vez. Esta charla aborda cómo construir personajes masculinos a través de la interpretación, el maquillaje, la silueta, el lenguaje corporal y la presencia escénica. Mediante ejemplos visuales y consejos prácticos, los asistentes aprenderán que el crossplay va mucho más allá del parecido físico y que una de sus claves está en transmitir la esencia del personaje. El objetivo es brindar confianza y herramientas para comenzar a explorar esta rama del cosplay.",
