    "descripcion": "Manuphilie\nUna chica del Eje Cafetero que encontró en internet un lugar para compartir lo que ama: anime, cosplays, videojuegos, Twitch y un montón de ideas que pasan por mi cabeza. ✨\nSatturnpower\nSoy Satturnpower, creadora de contenido y streamer de Medellín. Amo los videojuegos, especialmente los RPG, y soy fanática de Kingdom Hearts y Final Fantasy. También disfruto muchísimo el Just Chatting, hablar de cualquier cosa con mi comunidad, reírnos, compartir un rato y simplemente pasarla bien juntos.",
    "organizador": "Manuphilie & Satturnpower & Star cosplay",
