    "descripcion": "¿Y si pudieras llevarte un pedacito del tolima hecho por ti ?\nCon goma Eva de colores que veremos pequeñas figuras inspiradas en elementos de nuestra cultura y tradiciones \nMientras conocemos historias y significado detrás de los elementos más importantes de nuestra identidad",
