    "descripcion": "A inicios de abril, gracias a la misión Artemis, se abre una nueva ruta para la humanidad hacia las estrellas, retomando un camino que parecía haber quedado en pausa desde las misiones espaciales Apollo. Es un panorama prometedor para una humanidad que, a pesar de sus altibajos, ha logrado avanzar y evolucionar con el tiempo, convirtiendo poco a poco acontecimientos extraordinarios en parte de nuestra cotidianidad. El anime y manga Planetes, creado por Makoto Yukimura, autor de Vinland Saga, presenta precisamente una posible versión de ese futuro cotidiano en el que el espacio se ha convertido en un vecindario habitual.",
