    "descripcion": "PlayStation cumple 30 años como una de las marcas más influyentes de la industria de los videojuegos. Desde el lanzamiento de su primera consola en 1994 por Sony, revolucionó el entretenimiento digital mediante avances tecnológicos, narrativas más profundas y franquicias icónicas. A lo largo de sus diferentes generaciones, desde la PS1 hasta la PS5, PlayStation ha marcado tendencias y se ha consolidado como un referente global de innovación, entretenimiento y cultura gamer.",
    "organizador": "James Mendez",
