    "ubicacion": "Geek Academy (Espejo Rojo) · Salón conector 3",
    "descripcion": "La versión internacional de Pokémon experimentó diferentes cambios con respecto a la idea original. Entre ellos, se modificaron los nombres de numerosos personajes, alterando referencias y estructuras presentes en la versión japonesa. Esto aplica tanto a personajes humanos como a más del 90 % de los Pokémon. En esta charla analizaremos de manera educativa de dónde provienen algunos de sus nombres japoneses, cuál fue su inspiración y si habría sido conveniente conservarlos en japonés o si, por el contrario, era necesario traducirlos o adaptarlos.",
